package com.quicknotes.app;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
public class WidgetConfigActivity extends Activity {
 @Override public void onCreate(Bundle b){boolean dark=ReminderWidget.appDark(this);setTheme(dark?android.R.style.Theme_Material:android.R.style.Theme_Material_Light);super.onCreate(b);getWindow().setStatusBarColor(dark?0xff202124:0xfff2f2f7);getWindow().setNavigationBarColor(dark?0xff202124:0xfff2f2f7);setResult(RESULT_CANCELED);int id=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1);if(id<0){finish();return;}LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(32,32,32,32);box.setBackgroundColor(dark?0xff202124:0xfff2f2f7);setContentView(box);TextView title=new TextView(this);title.setText("Customize QuickNotes widget\nList · earliest due reminders first");title.setTextColor(dark?0xffeeeeee:0xff222222);title.setTextSize(22);box.addView(title);List<String> ids=new ArrayList<>(Arrays.asList("all","scheduled","today","flagged")),names=new ArrayList<>(Arrays.asList("All","Scheduled","Today","Flagged"));JSONArray ls=ReminderWidget.read(this).optJSONArray("lists");if(ls!=null)for(int n=0;n<ls.length();n++){JSONObject l=ls.optJSONObject(n);if(l!=null&&!l.optBoolean("deleted")){ids.add(l.optString("id"));names.add(l.optString("title"));}}Spinner list=new Spinner(this);list.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));list.setSelection(Math.max(0,ids.indexOf(ReminderWidget.prefs(this).getString(id+"list","all"))));box.addView(list);Spinner theme=new Spinner(this);List<String> themes=Arrays.asList("app","system","light","dark");theme.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,Arrays.asList("App theme","System theme","Light","Dark")));theme.setSelection(Math.max(0,themes.indexOf(ReminderWidget.prefs(this).getString(id+"theme","app"))));box.addView(theme);TextView help=new TextView(this);help.setText("Resize the widget on your home screen. Tap + to create a reminder, a row to edit it, or ⚙ to change these options.");help.setTextColor(dark?0xffcccccc:0xff555555);box.addView(help);Button save=new Button(this);save.setText("Save widget");box.addView(save);save.setOnClickListener(v->{ReminderWidget.prefs(this).edit().putString(id+"list",ids.get(list.getSelectedItemPosition())).putString(id+"theme",themes.get(theme.getSelectedItemPosition())).apply();ReminderWidget.update(this,id);setResult(RESULT_OK,new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id));finish();});}
}
